content.text:
{
  "name": "NI-DAQ任务等待线程",
  "name_en": "NI-DAQ Task Wait Thread",
  "manufacturer": "",
  "description": "用于实验控制流程中的非物理软件组件。它以线程方式连接任务对象、运行等待逻辑并执行关闭操作，适合配合 NI-DAQ 相关任务的异步执行与生命周期管理。",
  "description_en": "A non-physical software component used in laboratory control workflows. It runs as a thread to attach to a task object, execute waiting logic, and handle closure, supporting asynchronous execution and lifecycle management of NI-DAQ-related tasks.",
  "actions": [
    {
      "action_name": "auto-run",
      "description": "在线程中运行并等待已连接任务的执行流程。",
      "description_en": "Run the thread and wait on the execution flow of the connected task."
    },
    {
      "action_name": "auto-close",
      "description": "关闭等待线程及其关联任务流程。",
      "description_en": "Close the wait thread and its associated task flow."
    }
  ],
  "tag_hints": [
    "NI-DAQ task control",
    "asynchronous task handling",
    "threaded experiment control",
    "task lifecycle management",
    "lab automation helper"
  ]
}

